// A wobbling mirror ball in a panorama. iTexture0 is an equirectangular photo: a full 360°
// view with the direction around across it and the height up it. Every few seconds the ball
// is pulled out of shape, into a spherical harmonic (one of the natural ways a sphere can
// vibrate), then let go to spring back and wobble to a stop. Each pixel casts a ray from a
// camera circling the ball. Rays that miss show the panorama; rays that hit bounce off and
// show it in reflection. iFloat0 on the timeline is how far the ball is pulled each time:
// try changing the values, or adding more steps.
#define strength iFloat0
#define PI 3.14159265
#define SECONDS_PER_MODE 3.0

// The colour of the panorama seen in direction dir.
vec3 panorama(vec3 dir) {
  float around = atan(dir.z, dir.x) / (2.0 * PI) + 0.5;
  float up = asin(clamp(dir.y, -1.0, 1.0)) / PI + 0.5;
  vec2 uv = vec2(around, up);
  // Where the photo's left and right edges meet, "around" jumps from 1 back to 0. Texture
  // lookups take that jump as the picture being squashed, and blur a line of pixels. Giving
  // the lookup how fast uv changes between pixels, without the jump, avoids the seam.
  vec2 dx = dFdx(uv);
  vec2 dy = dFdy(uv);
  dx.x -= round(dx.x);
  dy.x -= round(dy.x);
  return textureGrad(iTexture0, uv, dx, dy).rgb;
}

// Six spherical harmonics, as functions of a direction n, each scaled to range about -1 to 1.
// Here y is the ball's up axis.
float harmonic(int mode, vec3 n) {
  float x = n.x, y = n.z, z = n.y;
  if (mode == 0) return 0.5 * (3.0 * z * z - 1.0);
  if (mode == 1) return x * x - y * y;
  if (mode == 2) return 0.75 * x * (5.0 * z * z - 1.0);
  if (mode == 3) return x * x * x - 3.0 * x * y * y;
  if (mode == 4) return (35.0 * z * z * z * z - 30.0 * z * z + 3.0) / 8.0;
  return x * x * x * x - 6.0 * x * x * y * y + y * y * y * y;
}

// How far out of shape the ball is, s seconds after it starts being pulled. It's pulled out
// quickly and held for a moment, then let go. After that it moves like a damped spring
// starting at rest: it swings back past its round shape and wobbles, each swing smaller.
float pullAndRelease(float s) {
  float pullTime = 0.35;
  float releaseTime = 0.5;
  if (s < releaseTime) {
    return smoothstep(0.0, pullTime, s);
  }
  float t = s - releaseTime;
  float damping = 1.8;
  float frequency = 2.0 * PI * 2.2;
  return exp(-damping * t) * (cos(frequency * t) + damping / frequency * sin(frequency * t));
}

// The ball's radius in direction n at the current time, going through the six harmonics.
float radius(vec3 n) {
  float phase = iTime / SECONDS_PER_MODE;
  int mode = int(mod(floor(phase), 6.0));
  float amount = pullAndRelease(fract(phase) * SECONDS_PER_MODE);
  return 1.0 + strength * amount * harmonic(mode, n);
}

// Roughly how far p is from the ball's surface: negative inside.
float ballDistance(vec3 p) {
  return length(p) - radius(normalize(p));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -1 to 1.
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // A camera circling the ball and looking at it, bobbing up and down.
  float angle = 0.35 * iTime;
  vec3 camera = vec3(3.2 * sin(angle), 0.8 * sin(0.4 * iTime), 3.2 * cos(angle));
  vec3 forward = normalize(-camera);
  vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, forward);
  vec3 ray = normalize(1.6 * forward + uv.x * right + uv.y * up);

  // Ray marching: step along the ray by the distance to the surface, until we reach it. The
  // wobbly surface makes that distance a guess, so take smaller steps to be safe.
  float t = 0.0;
  bool hit = false;
  for (int i = 0; i < 80; i++) {
    float d = ballDistance(camera + t * ray);
    if (d < 0.001) {
      hit = true;
      break;
    }
    t += 0.6 * d;
    if (t > 6.0) break;
  }

  vec3 col = panorama(ray);
  if (hit) {
    // The surface normal: the direction in which the distance grows fastest.
    vec3 p = camera + t * ray;
    vec2 e = vec2(0.001, 0.0);
    vec3 normal = normalize(vec3(
      ballDistance(p + e.xyy) - ballDistance(p - e.xyy),
      ballDistance(p + e.yxy) - ballDistance(p - e.yxy),
      ballDistance(p + e.yyx) - ballDistance(p - e.yyx)));
    // Mirrors reflect more at grazing angles (the Fresnel effect).
    float fresnel = 0.6 + 0.4 * pow(1.0 - max(dot(-ray, normal), 0.0), 3.0);
    col = fresnel * panorama(reflect(ray, normal)) * vec3(1.0, 0.95, 0.9);
  }
  fragColor = vec4(col, 1.0);
}
